<?php
// One-time deploy script — upload to public/ then visit: ?t=deploy21cav2026
// Writes the fixed DocxBuilderService.php and self-deletes.
if (!isset($_GET['t']) || $_GET['t'] !== 'deploy21cav2026') {
    http_response_code(403);
    die('Forbidden');
}
$content = gzdecode(base64_decode(''));
// Script lives in public/ — project root is one level up
$target = dirname(__DIR__) . '/app/Services/DocxBuilderService.php';
if (!is_file($target)) { die('ERROR: target not found: ' . $target); }
$backup = $target . '.bak.' . date('Ymd_His');
copy($target, $backup);
if (file_put_contents($target, $content) === false) { die('WRITE FAILED: ' . $target); }
@unlink(__FILE__);
echo 'OK: DocxBuilderService.php updated (' . strlen($content) . ' bytes). Backup: ' . basename($backup) . '. Run: php artisan queue:restart';
